//! A*-based PCB autorouter for CodeYourPCB.
//!
//! Replaces the FreeRouting JAR dependency with a custom routing engine
//! that produces `RoutingResult` output compatible with the existing
//! `apply_routes()` pipeline.
//!
//! # Workflow
//!
//! 1. Build a [`RoutingGrid`] from a `BoardWorld` and design rules
//! 2. Call [`route_board()`] to run the A* router on all unrouted nets
//! 3. The returned [`RoutingResult`] contains segments and vias ready for `apply_routes()`
//!
//! # Example
//!
//! ```rust,ignore
//! use cypcb_autoroute::{route_board, AutorouteConfig};
//! use cypcb_rules::presets::{RulesPreset, PresetRuleSet};
//!
//! let config = AutorouteConfig::default();
//! let preset = RulesPreset::from_name("jlcpcb").unwrap();
//! let rules = PresetRuleSet::new(preset);
//! let result = route_board(&world, &library, &rules, &config);
//! ```

pub mod cost;
pub mod grid;
pub mod orchestrator;
pub mod pathfinder;

use cypcb_router::types::RoutingResult;
use cypcb_rules::RoutingRuleSet;
use cypcb_world::footprint::FootprintLibrary;
use cypcb_world::BoardWorld;

/// Configuration for the autorouter.
#[derive(Debug, Clone)]
pub struct AutorouteConfig {
    /// Grid resolution in nanometers. Smaller = more precise but slower.
    /// Default: derived from `min_clearance / 2` (~63µm for JLCPCB).
    /// Set to `None` to auto-derive from rules.
    pub grid_resolution_nm: Option<i64>,

    /// Maximum rip-up-and-retry iterations before giving up on a net.
    pub max_ripup_iterations: u32,

    /// Cost multiplier for placing vias. Higher = fewer vias.
    pub via_cost_multiplier: f64,

    /// Whether to prefer routing on the top layer when possible.
    pub prefer_top_layer: bool,
}

impl Default for AutorouteConfig {
    fn default() -> Self {
        Self {
            grid_resolution_nm: None,
            max_ripup_iterations: 10,
            via_cost_multiplier: 1.0,
            prefer_top_layer: true,
        }
    }
}

impl AutorouteConfig {
    /// Resolve the grid resolution: use explicit value or derive from rules.
    pub fn resolve_grid_resolution(&self, rules: &dyn RoutingRuleSet) -> i64 {
        self.grid_resolution_nm.unwrap_or_else(|| {
            let clearance = rules.constraints_for_net(0).min_clearance;
            // Half the minimum clearance gives good resolution
            (clearance.raw() / 2).max(10_000) // floor at 10µm
        })
    }
}

/// Route all unrouted nets on the board.
///
/// This is the main entry point for the autorouter. It builds a routing grid
/// from the board world and design rules, then attempts to route each net
/// using A* pathfinding with rip-up-and-retry.
///
/// # Arguments
///
/// * `world` - The board world containing components, pads, zones, and existing traces
/// * `library` - Footprint library for pad geometry lookup
/// * `rules` - Design rules providing clearances, widths, and via costs
/// * `config` - Autorouter configuration (grid resolution, iteration limits, etc.)
///
/// # Returns
///
/// A `RoutingResult` containing all generated route segments and vias, or a
/// failure status if routing could not complete.
pub fn route_board(
    world: &mut BoardWorld,
    library: &FootprintLibrary,
    rules: &dyn RoutingRuleSet,
    config: &AutorouteConfig,
) -> RoutingResult {
    let _span = tracing::info_span!("route_board").entered();

    let resolution = config.resolve_grid_resolution(rules);

    // Build grid
    let mut grid = match grid::RoutingGrid::from_board(world, library, rules, resolution) {
        Some(g) => g,
        None => return RoutingResult::failed("Failed to build routing grid (no board entity?)"),
    };

    // Extract ratsnest
    let ratsnest = orchestrator::extract_ratsnest(world, library);
    if ratsnest.is_empty() {
        tracing::info!("No nets to route");
        return RoutingResult::complete(Vec::new(), Vec::new());
    }

    // Order nets by priority
    let order = orchestrator::order_nets(&ratsnest);

    // Route all nets
    let loop_result = orchestrator::route_all_nets(&mut grid, &ratsnest, &order, rules, config);

    // Convert grid paths to segments and vias
    let mut all_segments = Vec::new();
    let mut all_vias = Vec::new();

    for net in &ratsnest {
        if let Some(paths) = loop_result.routed_paths.get(&net.net_id.id()) {
            let (segs, vias) =
                orchestrator::paths_to_segments(&grid, net.net_id, paths, rules);
            all_segments.extend(segs);
            all_vias.extend(vias);
        }
    }

    if loop_result.unrouted.is_empty() {
        tracing::info!(
            segments = all_segments.len(),
            vias = all_vias.len(),
            "All nets routed successfully"
        );
        RoutingResult::complete(all_segments, all_vias)
    } else {
        tracing::warn!(
            unrouted = loop_result.unrouted.len(),
            "Some nets could not be routed"
        );
        RoutingResult::partial(all_segments, all_vias, loop_result.unrouted.len())
    }
}

//! Routing result types.
//!
//! Types for representing autorouting results from FreeRouting.

use cypcb_core::{Nm, Point};
use cypcb_world::{Layer, NetId};

/// Status of the routing operation.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RoutingStatus {
    /// All nets successfully routed.
    Complete,
    /// Some nets could not be routed.
    Partial {
        /// Number of connections that could not be routed.
        unrouted_count: usize,
    },
    /// Routing failed completely.
    Failed {
        /// Error message or reason for failure.
        reason: String,
    },
}

impl RoutingStatus {
    /// Check if routing completed successfully.
    pub fn is_complete(&self) -> bool {
        matches!(self, RoutingStatus::Complete)
    }

    /// Check if routing failed.
    pub fn is_failed(&self) -> bool {
        matches!(self, RoutingStatus::Failed { .. })
    }
}

/// A single routed trace segment.
///
/// Represents a wire segment from the autorouter output.
/// Multiple segments form a complete trace path.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RouteSegment {
    /// The net this segment belongs to.
    pub net_id: NetId,
    /// Which copper layer this segment is on.
    pub layer: Layer,
    /// Trace width in nanometers.
    pub width: Nm,
    /// Start point of the segment.
    pub start: Point,
    /// End point of the segment.
    pub end: Point,
}

impl RouteSegment {
    /// Create a new route segment.
    pub fn new(net_id: NetId, layer: Layer, width: Nm, start: Point, end: Point) -> Self {
        RouteSegment {
            net_id,
            layer,
            width,
            start,
            end,
        }
    }

    /// Calculate the length of this segment in nanometers.
    pub fn length(&self) -> Nm {
        let dx = self.end.x.0 - self.start.x.0;
        let dy = self.end.y.0 - self.start.y.0;

        // Use i128 to prevent overflow during squared calculation
        let dx_squared = (dx as i128) * (dx as i128);
        let dy_squared = (dy as i128) * (dy as i128);

        let sum = dx_squared + dy_squared;
        let length = (sum as f64).sqrt() as i64;

        Nm(length)
    }
}

/// A via placement from the autorouter.
///
/// Vias connect traces between different copper layers.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ViaPlacement {
    /// The net this via belongs to.
    pub net_id: NetId,
    /// Center position of the via.
    pub position: Point,
    /// Drill hole diameter in nanometers.
    pub drill: Nm,
    /// Upper layer connection (typically TopCopper).
    pub start_layer: Layer,
    /// Lower layer connection (typically BottomCopper).
    pub end_layer: Layer,
}

impl ViaPlacement {
    /// Create a new via placement.
    pub fn new(
        net_id: NetId,
        position: Point,
        drill: Nm,
        start_layer: Layer,
        end_layer: Layer,
    ) -> Self {
        ViaPlacement {
            net_id,
            position,
            drill,
            start_layer,
            end_layer,
        }
    }

    /// Create a through-hole via (top to bottom copper).
    pub fn through_hole(net_id: NetId, position: Point, drill: Nm) -> Self {
        ViaPlacement {
            net_id,
            position,
            drill,
            start_layer: Layer::TopCopper,
            end_layer: Layer::BottomCopper,
        }
    }
}

/// Result of an autorouting operation.
///
/// Contains the routing status and all generated routes and vias.
#[derive(Debug, Clone)]
pub struct RoutingResult {
    /// Status of the routing operation.
    pub status: RoutingStatus,
    /// Generated trace segments.
    pub routes: Vec<RouteSegment>,
    /// Generated via placements.
    pub vias: Vec<ViaPlacement>,
}

impl RoutingResult {
    /// Create a successful routing result.
    pub fn complete(routes: Vec<RouteSegment>, vias: Vec<ViaPlacement>) -> Self {
        RoutingResult {
            status: RoutingStatus::Complete,
            routes,
            vias,
        }
    }

    /// Create a partial routing result.
    pub fn partial(
        routes: Vec<RouteSegment>,
        vias: Vec<ViaPlacement>,
        unrouted_count: usize,
    ) -> Self {
        RoutingResult {
            status: RoutingStatus::Partial { unrouted_count },
            routes,
            vias,
        }
    }

    /// Create a failed routing result.
    pub fn failed(reason: impl Into<String>) -> Self {
        RoutingResult {
            status: RoutingStatus::Failed {
                reason: reason.into(),
            },
            routes: Vec::new(),
            vias: Vec::new(),
        }
    }

    /// Check if routing completed successfully.
    pub fn is_complete(&self) -> bool {
        self.status.is_complete()
    }

    /// Get the total number of route segments.
    pub fn route_count(&self) -> usize {
        self.routes.len()
    }

    /// Get the total number of vias.
    pub fn via_count(&self) -> usize {
        self.vias.len()
    }

    /// Calculate the total routed wire length.
    pub fn total_length(&self) -> Nm {
        let total: i64 = self.routes.iter().map(|r| r.length().0).sum();
        Nm(total)
    }
}

impl Default for RoutingResult {
    fn default() -> Self {
        RoutingResult {
            status: RoutingStatus::Complete,
            routes: Vec::new(),
            vias: Vec::new(),
        }
    }
}

/// Quality metrics for routing results.
///
/// Used to evaluate the "satisfaction score" of a routing solution.
/// Lower values generally indicate better routing quality.
///
/// # Example
///
/// ```
/// use cypcb_router::types::RoutingMetrics;
/// use cypcb_core::Nm;
///
/// let metrics = RoutingMetrics {
///     total_length: Nm::from_mm(150.0),
///     via_count: 5,
///     layer_changes: 5,
///     unrouted_nets: 0,
/// };
///
/// assert!(metrics.is_complete());
/// ```
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct RoutingMetrics {
    /// Total routed wire length in nanometers.
    pub total_length: Nm,

    /// Number of vias used.
    pub via_count: u32,

    /// Number of layer changes (equals via_count for simple designs).
    pub layer_changes: u32,

    /// Number of nets that could not be routed.
    pub unrouted_nets: u32,
}

impl RoutingMetrics {
    /// Check if all nets were successfully routed.
    pub fn is_complete(&self) -> bool {
        self.unrouted_nets == 0
    }

    /// Calculate a simple quality score (lower is better).
    ///
    /// Scoring formula:
    /// - Base: total_length in mm
    /// - Penalty: +5mm per via
    /// - Penalty: +1000mm per unrouted net
    ///
    /// This provides a rough measure for comparing routing solutions.
    pub fn quality_score(&self) -> f64 {
        let length_mm = self.total_length.0 as f64 / 1_000_000.0;
        let via_penalty = self.via_count as f64 * 5.0;
        let unrouted_penalty = self.unrouted_nets as f64 * 1000.0;

        length_mm + via_penalty + unrouted_penalty
    }
}

/// Calculate routing metrics from a RoutingResult.
///
/// # Example
///
/// ```
/// use cypcb_router::types::{RoutingResult, RouteSegment, ViaPlacement, calculate_metrics};
/// use cypcb_world::{Layer, NetId};
/// use cypcb_core::{Nm, Point};
///
/// let routes = vec![
///     RouteSegment::new(NetId::new(0), Layer::TopCopper, Nm::from_mm(0.2),
///         Point::from_mm(0.0, 0.0), Point::from_mm(10.0, 0.0)),
/// ];
/// let vias = vec![
///     ViaPlacement::through_hole(NetId::new(0), Point::from_mm(10.0, 0.0), Nm::from_mm(0.3)),
/// ];
///
/// let result = RoutingResult::complete(routes, vias);
/// let metrics = calculate_metrics(&result);
///
/// assert_eq!(metrics.via_count, 1);
/// assert_eq!(metrics.total_length, Nm::from_mm(10.0));
/// ```
pub fn calculate_metrics(result: &RoutingResult) -> RoutingMetrics {
    let total_length = result.total_length();
    let via_count = result.vias.len() as u32;

    // Count layer changes (each via represents a layer change)
    let layer_changes = via_count;

    // Count unrouted nets from status
    let unrouted_nets = match &result.status {
        RoutingStatus::Complete => 0,
        RoutingStatus::Partial { unrouted_count } => *unrouted_count as u32,
        RoutingStatus::Failed { .. } => u32::MAX, // Unknown, assume worst
    };

    RoutingMetrics {
        total_length,
        via_count,
        layer_changes,
        unrouted_nets,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_routing_status() {
        assert!(RoutingStatus::Complete.is_complete());
        assert!(!RoutingStatus::Complete.is_failed());

        let partial = RoutingStatus::Partial { unrouted_count: 5 };
        assert!(!partial.is_complete());
        assert!(!partial.is_failed());

        let failed = RoutingStatus::Failed {
            reason: "timeout".into(),
        };
        assert!(!failed.is_complete());
        assert!(failed.is_failed());
    }

    #[test]
    fn test_route_segment() {
        let seg = RouteSegment::new(
            NetId::new(0),
            Layer::TopCopper,
            Nm::from_mm(0.2),
            Point::from_mm(0.0, 0.0),
            Point::from_mm(10.0, 0.0),
        );

        assert_eq!(seg.net_id, NetId::new(0));
        assert_eq!(seg.layer, Layer::TopCopper);
        assert_eq!(seg.width, Nm::from_mm(0.2));
        assert_eq!(seg.length(), Nm::from_mm(10.0));
    }

    #[test]
    fn test_route_segment_diagonal() {
        // 3-4-5 triangle
        let seg = RouteSegment::new(
            NetId::new(0),
            Layer::TopCopper,
            Nm::from_mm(0.2),
            Point::from_mm(0.0, 0.0),
            Point::from_mm(3.0, 4.0),
        );

        assert_eq!(seg.length(), Nm::from_mm(5.0));
    }

    #[test]
    fn test_via_placement() {
        let via = ViaPlacement::through_hole(
            NetId::new(1),
            Point::from_mm(5.0, 5.0),
            Nm::from_mm(0.3),
        );

        assert_eq!(via.net_id, NetId::new(1));
        assert_eq!(via.position, Point::from_mm(5.0, 5.0));
        assert_eq!(via.drill, Nm::from_mm(0.3));
        assert_eq!(via.start_layer, Layer::TopCopper);
        assert_eq!(via.end_layer, Layer::BottomCopper);
    }

    #[test]
    fn test_routing_result_complete() {
        let routes = vec![RouteSegment::new(
            NetId::new(0),
            Layer::TopCopper,
            Nm::from_mm(0.2),
            Point::from_mm(0.0, 0.0),
            Point::from_mm(10.0, 0.0),
        )];
        let vias = vec![ViaPlacement::through_hole(
            NetId::new(0),
            Point::from_mm(10.0, 0.0),
            Nm::from_mm(0.3),
        )];

        let result = RoutingResult::complete(routes, vias);

        assert!(result.is_complete());
        assert_eq!(result.route_count(), 1);
        assert_eq!(result.via_count(), 1);
        assert_eq!(result.total_length(), Nm::from_mm(10.0));
    }

    #[test]
    fn test_routing_result_partial() {
        let result = RoutingResult::partial(Vec::new(), Vec::new(), 3);

        assert!(!result.is_complete());
        assert_eq!(result.route_count(), 0);

        if let RoutingStatus::Partial { unrouted_count } = result.status {
            assert_eq!(unrouted_count, 3);
        } else {
            panic!("Expected Partial status");
        }
    }

    #[test]
    fn test_routing_result_failed() {
        let result = RoutingResult::failed("Process crashed");

        assert!(!result.is_complete());
        assert!(result.routes.is_empty());
        assert!(result.vias.is_empty());

        if let RoutingStatus::Failed { reason } = result.status {
            assert_eq!(reason, "Process crashed");
        } else {
            panic!("Expected Failed status");
        }
    }

    #[test]
    fn test_routing_result_default() {
        let result = RoutingResult::default();

        assert!(result.is_complete());
        assert!(result.routes.is_empty());
        assert!(result.vias.is_empty());
    }

    #[test]
    fn test_routing_metrics_complete() {
        let metrics = RoutingMetrics {
            total_length: Nm::from_mm(100.0),
            via_count: 3,
            layer_changes: 3,
            unrouted_nets: 0,
        };

        assert!(metrics.is_complete());
    }

    #[test]
    fn test_routing_metrics_incomplete() {
        let metrics = RoutingMetrics {
            total_length: Nm::from_mm(50.0),
            via_count: 1,
            layer_changes: 1,
            unrouted_nets: 2,
        };

        assert!(!metrics.is_complete());
    }

    #[test]
    fn test_routing_metrics_quality_score() {
        // Simple case: 100mm length, 0 vias, 0 unrouted
        let metrics = RoutingMetrics {
            total_length: Nm::from_mm(100.0),
            via_count: 0,
            layer_changes: 0,
            unrouted_nets: 0,
        };

        // Score should be just the length
        assert!((metrics.quality_score() - 100.0).abs() < 0.01);

        // With vias
        let metrics_with_vias = RoutingMetrics {
            total_length: Nm::from_mm(100.0),
            via_count: 2,
            layer_changes: 2,
            unrouted_nets: 0,
        };

        // Score = 100 + (2 * 5) = 110
        assert!((metrics_with_vias.quality_score() - 110.0).abs() < 0.01);
    }

    #[test]
    fn test_calculate_metrics_complete() {
        let routes = vec![
            RouteSegment::new(
                NetId::new(0),
                Layer::TopCopper,
                Nm::from_mm(0.2),
                Point::from_mm(0.0, 0.0),
                Point::from_mm(10.0, 0.0),
            ),
            RouteSegment::new(
                NetId::new(0),
                Layer::BottomCopper,
                Nm::from_mm(0.2),
                Point::from_mm(10.0, 0.0),
                Point::from_mm(20.0, 0.0),
            ),
        ];
        let vias = vec![ViaPlacement::through_hole(
            NetId::new(0),
            Point::from_mm(10.0, 0.0),
            Nm::from_mm(0.3),
        )];

        let result = RoutingResult::complete(routes, vias);
        let metrics = calculate_metrics(&result);

        assert_eq!(metrics.total_length, Nm::from_mm(20.0));
        assert_eq!(metrics.via_count, 1);
        assert_eq!(metrics.layer_changes, 1);
        assert_eq!(metrics.unrouted_nets, 0);
        assert!(metrics.is_complete());
    }

    #[test]
    fn test_calculate_metrics_partial() {
        let routes = vec![RouteSegment::new(
            NetId::new(0),
            Layer::TopCopper,
            Nm::from_mm(0.2),
            Point::from_mm(0.0, 0.0),
            Point::from_mm(5.0, 0.0),
        )];

        let result = RoutingResult::partial(routes, Vec::new(), 3);
        let metrics = calculate_metrics(&result);

        assert_eq!(metrics.total_length, Nm::from_mm(5.0));
        assert_eq!(metrics.via_count, 0);
        assert_eq!(metrics.unrouted_nets, 3);
        assert!(!metrics.is_complete());
    }

    #[test]
    fn test_routing_metrics_default() {
        let metrics = RoutingMetrics::default();

        assert_eq!(metrics.total_length, Nm(0));
        assert_eq!(metrics.via_count, 0);
        assert_eq!(metrics.layer_changes, 0);
        assert_eq!(metrics.unrouted_nets, 0);
        assert!(metrics.is_complete());
    }
}

//! Net ordering and routing orchestration.
//!
//! This module is the "brain" of the autorouter. It:
//! 1. Extracts the ratsnest (unrouted connections) from `BoardWorld`
//! 2. Orders nets by routing priority (short first, power last)
//! 3. Routes each net sequentially using A* pathfinding
//! 4. Handles congestion via rip-up/reroute when a net fails

use std::collections::HashMap;

use cypcb_core::{Nm, Point};
use cypcb_router::types::{RouteSegment, ViaPlacement};
use cypcb_rules::RoutingRuleSet;
use cypcb_world::footprint::FootprintLibrary;
use cypcb_world::{BoardWorld, FootprintRef, NetConnections, NetId, Position, Rotation};

use crate::cost::RoutingCost;
use crate::grid::{index_to_layer, layer_to_index, RoutingGrid};
use crate::pathfinder::{find_path_with_zones, GridNode, PadZone};
use crate::AutorouteConfig;

/// A pad target for routing — the absolute position and layer info of a single pad.
#[derive(Debug, Clone)]
pub struct PadTarget {
    /// Absolute board position in nanometers.
    pub position: Point,
    /// Copper layer mask (bit 0 = top, bit 1 = bottom, ...).
    pub layer_mask: u32,
    /// Pad size (width, height) in nanometers.
    pub pad_size: (Nm, Nm),
    /// Pin name/number for diagnostics.
    pub pin: String,
}

/// A net and its pad targets for routing.
#[derive(Debug, Clone)]
pub struct NetRoute {
    /// The net ID.
    pub net_id: NetId,
    /// The net name (for diagnostics and power/ground detection).
    pub net_name: String,
    /// All pad targets belonging to this net.
    pub pads: Vec<PadTarget>,
}

/// A point-to-point connection within a net (one edge of the spanning tree).
#[derive(Debug, Clone)]
struct Connection {
    from_idx: usize,
    to_idx: usize,
}

/// Extract the ratsnest from a board world.
///
/// For each net, collects all pin pads that belong to it by iterating
/// components and matching pin connections against the footprint library.
pub fn extract_ratsnest(
    world: &mut BoardWorld,
    library: &FootprintLibrary,
) -> Vec<NetRoute> {
    let _span = tracing::info_span!("extract_ratsnest").entered();

    // Collect component data: (position, rotation_deg, footprint_name, net_connections)
    let components: Vec<(Point, f64, String, NetConnections)> = {
        let ecs = world.ecs_mut();
        let mut query = ecs.query::<(&Position, &Rotation, &FootprintRef, &NetConnections)>();
        query
            .iter(ecs)
            .map(|(pos, rot, fp, nets)| {
                (pos.0, rot.to_degrees(), fp.as_str().to_string(), nets.clone())
            })
            .collect()
    };

    // Build a map: net_id -> Vec<PadTarget>
    let mut net_pads: HashMap<NetId, Vec<PadTarget>> = HashMap::new();

    for (comp_pos, rotation_deg, fp_name, net_conns) in &components {
        let footprint = match library.get(fp_name) {
            Some(fp) => fp,
            None => {
                tracing::warn!(footprint = %fp_name, "Footprint not found in library, skipping");
                continue;
            }
        };

        for pin_conn in net_conns.iter() {
            // Find the pad definition for this pin
            let pad_def = match footprint.get_pad(&pin_conn.pin) {
                Some(p) => p,
                None => {
                    tracing::debug!(
                        pin = %pin_conn.pin,
                        footprint = %fp_name,
                        "Pin not found in footprint"
                    );
                    continue;
                }
            };

            // Compute absolute pad position
            let pad_pos = rotate_point(pad_def.position, *rotation_deg);
            let abs_pos = Point::new(
                Nm::new(comp_pos.x.raw() + pad_pos.x.raw()),
                Nm::new(comp_pos.y.raw() + pad_pos.y.raw()),
            );

            // Compute layer mask from pad layers
            let mut layer_mask = 0u32;
            for layer in &pad_def.layers {
                if let Some(idx) = layer_to_index(*layer) {
                    layer_mask |= 1u32 << idx;
                }
            }

            net_pads
                .entry(pin_conn.net)
                .or_default()
                .push(PadTarget {
                    position: abs_pos,
                    layer_mask,
                    pad_size: pad_def.size,
                    pin: pin_conn.pin.clone(),
                });
        }
    }

    // Collect net names and build NetRoutes
    let mut ratsnest = Vec::new();
    // Sort by net ID for determinism
    let mut net_ids: Vec<NetId> = net_pads.keys().copied().collect();
    net_ids.sort_by_key(|n| n.id());

    for net_id in net_ids {
        let pads = net_pads.remove(&net_id).unwrap();
        if pads.len() < 2 {
            // Single-pad nets don't need routing (e.g., SIGNAL with one pin)
            continue;
        }

        let net_name = world
            .net_name(net_id)
            .unwrap_or("unnamed")
            .to_string();

        tracing::debug!(
            net_id = net_id.id(),
            net_name = %net_name,
            pad_count = pads.len(),
            "Net extracted"
        );

        ratsnest.push(NetRoute {
            net_id,
            net_name,
            pads,
        });
    }

    tracing::info!(net_count = ratsnest.len(), "Ratsnest extracted");
    ratsnest
}

/// Order nets by routing priority.
///
/// Priority rules:
/// 1. Critical nets (HighSpeed signal class) go first
/// 2. Short nets (smallest Manhattan span) before long ones
/// 3. Power/ground nets go last
///
/// Returns indices into the ratsnest slice, sorted by priority.
pub fn order_nets(ratsnest: &[NetRoute]) -> Vec<usize> {
    let mut indices: Vec<usize> = (0..ratsnest.len()).collect();

    indices.sort_by(|&a, &b| {
        let net_a = &ratsnest[a];
        let net_b = &ratsnest[b];

        let a_power = is_power_net(&net_a.net_name);
        let b_power = is_power_net(&net_b.net_name);

        // Power nets go last
        match (a_power, b_power) {
            (true, false) => return std::cmp::Ordering::Greater,
            (false, true) => return std::cmp::Ordering::Less,
            _ => {}
        }

        // Sort by Manhattan span (shorter first)
        let a_span = manhattan_span(&net_a.pads);
        let b_span = manhattan_span(&net_b.pads);
        a_span.cmp(&b_span)
    });

    indices
}

/// Check if a net name indicates power or ground.
fn is_power_net(name: &str) -> bool {
    let upper = name.to_uppercase();
    matches!(
        upper.as_str(),
        "VCC" | "VDD" | "GND" | "VSS" | "5V" | "3V3" | "3.3V" | "12V" | "1V8" | "1.8V"
            | "+5V" | "+3V3" | "+3.3V" | "+12V" | "+1V8" | "+1.8V"
            | "VBAT" | "VBUS" | "V+" | "V-"
    )
}

/// Compute the total Manhattan span of a set of pads (bounding box perimeter proxy).
fn manhattan_span(pads: &[PadTarget]) -> i64 {
    if pads.is_empty() {
        return 0;
    }
    let mut min_x = i64::MAX;
    let mut max_x = i64::MIN;
    let mut min_y = i64::MAX;
    let mut max_y = i64::MIN;

    for pad in pads {
        let x = pad.position.x.raw();
        let y = pad.position.y.raw();
        min_x = min_x.min(x);
        max_x = max_x.max(x);
        min_y = min_y.min(y);
        max_y = max_y.max(y);
    }

    (max_x - min_x) + (max_y - min_y)
}

/// Build a minimum spanning tree of pad positions using greedy nearest-neighbor.
///
/// Returns ordered connections (edges) between pad indices.
fn build_spanning_tree(pads: &[PadTarget]) -> Vec<Connection> {
    if pads.len() < 2 {
        return Vec::new();
    }

    let n = pads.len();
    let mut in_tree = vec![false; n];
    let mut connections = Vec::with_capacity(n - 1);

    // Start from pad 0
    in_tree[0] = true;
    let mut tree_count = 1;

    while tree_count < n {
        let mut best_from = 0;
        let mut best_to = 0;
        let mut best_dist = i64::MAX;

        for (i, &in_t) in in_tree.iter().enumerate() {
            if !in_t {
                continue;
            }
            for (j, &in_t_j) in in_tree.iter().enumerate() {
                if in_t_j {
                    continue;
                }
                let dist = manhattan_distance(&pads[i].position, &pads[j].position);
                if dist < best_dist {
                    best_dist = dist;
                    best_from = i;
                    best_to = j;
                }
            }
        }

        in_tree[best_to] = true;
        tree_count += 1;
        connections.push(Connection {
            from_idx: best_from,
            to_idx: best_to,
        });
    }

    connections
}

fn manhattan_distance(a: &Point, b: &Point) -> i64 {
    (a.x.raw() - b.x.raw()).abs() + (a.y.raw() - b.y.raw()).abs()
}

/// Result of routing all nets.
pub struct RoutingLoopResult {
    /// Per-net routed grid paths.
    pub routed_paths: HashMap<u32, Vec<Vec<GridNode>>>,
    /// Net IDs that could not be routed.
    pub unrouted: Vec<u32>,
    /// Total via count across all nets.
    pub total_vias: usize,
}

/// Route all nets on the grid with rip-up/reroute.
pub fn route_all_nets(
    grid: &mut RoutingGrid,
    ratsnest: &[NetRoute],
    order: &[usize],
    rules: &dyn RoutingRuleSet,
    config: &AutorouteConfig,
) -> RoutingLoopResult {
    let _span = tracing::info_span!("route_all_nets").entered();

    // Track routed paths per net (net_id -> list of paths)
    let mut routed_paths: HashMap<u32, Vec<Vec<GridNode>>> = HashMap::new();
    let mut unrouted: Vec<u32> = Vec::new();

    for &net_idx in order {
        let net = &ratsnest[net_idx];
        let net_id = net.net_id.id();
        let connections = build_spanning_tree(&net.pads);

        let _net_span = tracing::info_span!(
            "route_net",
            net_id = net_id,
            net_name = %net.net_name,
            connections = connections.len(),
        )
        .entered();

        tracing::info!(
            net_id = net_id,
            net_name = %net.net_name,
            connection_count = connections.len(),
            "Routing net"
        );

        let mut net_success = true;
        let mut net_paths: Vec<Vec<GridNode>> = Vec::new();

        // Compute pad zones for all pads in this net
        let net_pad_zones: Vec<PadZone> = net
            .pads
            .iter()
            .map(|pad| pad_to_zone(grid, pad))
            .collect();

        for conn in &connections {
            let from_pad = &net.pads[conn.from_idx];
            let to_pad = &net.pads[conn.to_idx];

            let start = pad_to_grid_node(grid, from_pad);
            let end = pad_to_grid_node(grid, to_pad);

            // Determine if end pad is through-hole (can end on any layer)
            let any_end = is_multi_layer(to_pad.layer_mask);

            let cost = RoutingCost::new(rules, net_id, config.via_cost_multiplier);

            // Try to route directly
            match find_path_with_zones(grid, start, end, &cost, any_end, &net_pad_zones) {
                Some(path) => {
                    net_paths.push(path);
                }
                None => {
                    // Rip-up/reroute: find blocking net and retry
                    let conn_attempt = ConnectionAttempt {
                        start,
                        end,
                        any_end,
                        net_id,
                        pad_zones: &net_pad_zones,
                    };
                    let routed = attempt_ripup_reroute(
                        grid,
                        &conn_attempt,
                        &mut routed_paths,
                        ratsnest,
                        rules,
                        config,
                    );
                    match routed {
                        Some(path) => {
                            net_paths.push(path);
                        }
                        None => {
                            tracing::warn!(
                                net_id = net_id,
                                net_name = %net.net_name,
                                from_pin = %from_pad.pin,
                                to_pin = %to_pad.pin,
                                "Connection failed after rip-up attempts"
                            );
                            net_success = false;
                        }
                    }
                }
            }
        }

        if net_success && !connections.is_empty() {
            tracing::info!(
                net_id = net_id,
                net_name = %net.net_name,
                path_count = net_paths.len(),
                "Net routed successfully"
            );
            routed_paths.insert(net_id, net_paths);
        } else if !connections.is_empty() {
            // Partial route — still record what we got
            tracing::warn!(
                net_id = net_id,
                net_name = %net.net_name,
                "Net partially routed"
            );
            routed_paths.insert(net_id, net_paths);
            unrouted.push(net_id);
        }
    }

    // Count total vias
    let total_vias: usize = routed_paths
        .values()
        .flat_map(|paths| paths.iter())
        .map(|path| path.windows(2).filter(|w| w[0].2 != w[1].2).count())
        .sum();

    let routed_count = ratsnest.len() - unrouted.len();
    tracing::info!(
        routed = routed_count,
        total = ratsnest.len(),
        vias = total_vias,
        "Routing complete"
    );

    RoutingLoopResult {
        routed_paths,
        unrouted,
        total_vias,
    }
}

/// Parameters for a single connection routing attempt.
struct ConnectionAttempt<'a> {
    start: GridNode,
    end: GridNode,
    any_end: bool,
    net_id: u32,
    pad_zones: &'a [PadZone],
}

/// Attempt rip-up/reroute to resolve congestion.
///
/// Searches around the start/end for blocking nets, rips up the most
/// likely blocker, routes the current net, then re-routes the victim.
#[allow(clippy::too_many_arguments)]
fn attempt_ripup_reroute(
    grid: &mut RoutingGrid,
    attempt: &ConnectionAttempt<'_>,
    routed_paths: &mut HashMap<u32, Vec<Vec<GridNode>>>,
    ratsnest: &[NetRoute],
    rules: &dyn RoutingRuleSet,
    config: &AutorouteConfig,
) -> Option<Vec<GridNode>> {
    let max_iters = config.max_ripup_iterations;
    let current_net_id = attempt.net_id;

    for iter in 0..max_iters {
        // Find a blocking net near the endpoints
        let victim_id = find_blocking_net(grid, attempt.start, attempt.end);

        let victim_id = match victim_id {
            Some(id) if id != current_net_id => id,
            _ => {
                tracing::debug!(
                    iter,
                    current_net = current_net_id,
                    "No suitable victim net found for rip-up"
                );
                return None;
            }
        };

        tracing::warn!(
            iter,
            victim = victim_id,
            current = current_net_id,
            "Rip-up: removing net to make way"
        );

        // Save victim's paths before clearing
        let victim_paths = routed_paths.remove(&victim_id);

        // Clear victim from grid
        grid.clear_route(victim_id);

        // Try routing current net
        let cost = RoutingCost::new(rules, current_net_id, config.via_cost_multiplier);
        if let Some(path) = find_path_with_zones(grid, attempt.start, attempt.end, &cost, attempt.any_end, attempt.pad_zones) {
            // Current net routed. Now re-route victim.
            if let Some(old_paths) = victim_paths {
                let victim_cost = RoutingCost::new(rules, victim_id, config.via_cost_multiplier);
                let mut victim_rerouted = Vec::new();
                let mut victim_ok = true;

                // Find the victim's net route info for pad targets
                let victim_net = ratsnest.iter().find(|n| n.net_id.id() == victim_id);
                if let Some(victim_net) = victim_net {
                    let victim_pad_zones: Vec<PadZone> = victim_net
                        .pads
                        .iter()
                        .map(|pad| pad_to_zone(grid, pad))
                        .collect();
                    let victim_conns = build_spanning_tree(&victim_net.pads);
                    for conn in &victim_conns {
                        let v_start = pad_to_grid_node(grid, &victim_net.pads[conn.from_idx]);
                        let v_end = pad_to_grid_node(grid, &victim_net.pads[conn.to_idx]);
                        let v_any_end =
                            is_multi_layer(victim_net.pads[conn.to_idx].layer_mask);

                        match find_path_with_zones(grid, v_start, v_end, &victim_cost, v_any_end, &victim_pad_zones) {
                            Some(vp) => victim_rerouted.push(vp),
                            None => {
                                victim_ok = false;
                                break;
                            }
                        }
                    }
                }

                if victim_ok {
                    tracing::info!(
                        victim = victim_id,
                        "Victim net re-routed successfully"
                    );
                    if !victim_rerouted.is_empty() {
                        routed_paths.insert(victim_id, victim_rerouted);
                    }
                    return Some(path);
                } else {
                    // Re-routing victim failed. Undo: clear current net, restore victim.
                    tracing::debug!(
                        victim = victim_id,
                        "Victim re-route failed, restoring"
                    );
                    // Clear what we just routed for current net
                    grid.clear_route(current_net_id);
                    // Remove path cells we added
                    // Restore victim's original paths
                    for old_path in &old_paths {
                        for node in old_path {
                            grid.mark_route(
                                node.0 as u32,
                                node.1 as u32,
                                node.2 as usize,
                                victim_id,
                            );
                        }
                    }
                    routed_paths.insert(victim_id, old_paths);
                    // Try next iteration with a different victim
                    continue;
                }
            }

            return Some(path);
        } else {
            // Current net still can't route even with victim removed. Restore victim.
            if let Some(old_paths) = victim_paths {
                for old_path in &old_paths {
                    for node in old_path {
                        grid.mark_route(
                            node.0 as u32,
                            node.1 as u32,
                            node.2 as usize,
                            victim_id,
                        );
                    }
                }
                routed_paths.insert(victim_id, old_paths);
            }
        }
    }

    None
}

/// Find the net that is most likely blocking routing between start and end.
///
/// Samples points along the direct line from start to end and searches
/// around each sample for occupied cells owned by other nets. This finds
/// blockers anywhere along the path, not just near endpoints.
fn find_blocking_net(grid: &RoutingGrid, start: GridNode, end: GridNode) -> Option<u32> {
    let search_radius = 3u32;
    let mut net_counts: HashMap<u32, u32> = HashMap::new();

    // Sample points along the line from start to end
    let dx = end.0 as i32 - start.0 as i32;
    let dy = end.1 as i32 - start.1 as i32;
    let steps = (dx.abs().max(dy.abs()) as u32).max(1);
    // Sample at most ~10 points to keep it fast
    let sample_step = (steps / 10).max(1);

    let mut i = 0u32;
    while i <= steps {
        let t = i as f64 / steps as f64;
        let sx = start.0 as f64 + dx as f64 * t;
        let sy = start.1 as f64 + dy as f64 * t;
        let cx = sx.round() as u32;
        let cy = sy.round() as u32;

        for layer in 0..grid.layer_count() as usize {
            let min_x = cx.saturating_sub(search_radius);
            let max_x = (cx + search_radius).min(grid.width().saturating_sub(1));
            let min_y = cy.saturating_sub(search_radius);
            let max_y = (cy + search_radius).min(grid.height().saturating_sub(1));

            for y in min_y..=max_y {
                for x in min_x..=max_x {
                    if let Some(net_id) = grid.net_at(x, y, layer) {
                        *net_counts.entry(net_id).or_insert(0) += 1;
                    }
                }
            }
        }

        i += sample_step;
        // Always include the last point
        if i > steps && i - sample_step < steps {
            i = steps;
        }
    }

    // Return the net with the most cells along the path
    net_counts
        .into_iter()
        .max_by_key(|&(_, count)| count)
        .map(|(net_id, _)| net_id)
}

/// Convert a PadTarget to the best GridNode for routing.
fn pad_to_grid_node(grid: &RoutingGrid, pad: &PadTarget) -> GridNode {
    let (gx, gy) = grid.nm_to_grid(pad.position);
    // Pick the preferred layer from the layer mask
    let layer = preferred_layer(pad.layer_mask);
    (gx as u16, gy as u16, layer)
}

/// Compute a PadZone (allowed area) for a pad target.
///
/// The zone radius covers the pad's physical extent plus one cell of margin,
/// so that routes can enter and exit the pad even though it's marked as an obstacle.
fn pad_to_zone(grid: &RoutingGrid, pad: &PadTarget) -> PadZone {
    let (gx, gy) = grid.nm_to_grid(pad.position);
    let pad_radius_nm = pad.pad_size.0.raw().max(pad.pad_size.1.raw()) / 2;
    // Pad radius in grid cells, plus clearance bloat, plus 1 cell margin
    let pad_radius_cells =
        ((pad_radius_nm + grid.resolution() - 1) / grid.resolution()) as u16;
    // Add clearance cells (approx same as during grid construction) + margin
    let clearance_cells = 3u16; // Generous but safe
    PadZone {
        cx: gx as u16,
        cy: gy as u16,
        radius: pad_radius_cells + clearance_cells,
    }
}

/// Pick the preferred routing layer from a layer mask.
/// Prefers top copper (layer 0) if available.
fn preferred_layer(layer_mask: u32) -> u8 {
    if layer_mask & 1 != 0 {
        0 // Top copper
    } else {
        // Find lowest set bit
        layer_mask.trailing_zeros() as u8
    }
}

/// Check if a layer mask covers multiple copper layers (through-hole pad).
fn is_multi_layer(layer_mask: u32) -> bool {
    layer_mask.count_ones() > 1
}

/// Convert grid paths to RouteSegments and ViasPlacements.
///
/// Basic conversion: each pair of adjacent grid nodes with the same layer
/// becomes a segment. Layer changes become vias.
pub fn paths_to_segments(
    grid: &RoutingGrid,
    net_id: NetId,
    paths: &[Vec<GridNode>],
    rules: &dyn RoutingRuleSet,
) -> (Vec<RouteSegment>, Vec<ViaPlacement>) {
    let constraints = rules.constraints_for_net(net_id.id());
    let trace_width = constraints.min_trace_width;
    let via_drill = constraints.min_via_drill;

    let mut segments = Vec::new();
    let mut vias = Vec::new();

    for path in paths {
        if path.len() < 2 {
            continue;
        }

        // Walk the path, accumulating collinear segments on the same layer
        let mut seg_start = path[0];
        let mut prev = path[0];

        for &node in &path[1..] {
            if node.2 != prev.2 {
                // Layer change — emit segment up to prev, then a via
                if seg_start != prev {
                    segments.push(make_segment(grid, net_id, seg_start, prev, trace_width));
                }

                let via_pos = grid.grid_to_nm(prev.0 as u32, prev.1 as u32);
                vias.push(ViaPlacement::new(
                    net_id,
                    via_pos,
                    via_drill,
                    index_to_layer(prev.2 as usize),
                    index_to_layer(node.2 as usize),
                ));

                seg_start = node;
            } else {
                // Same layer — check if direction changed
                let dx1 = prev.0 as i32 - seg_start.0 as i32;
                let dy1 = prev.1 as i32 - seg_start.1 as i32;
                let dx2 = node.0 as i32 - prev.0 as i32;
                let dy2 = node.1 as i32 - prev.1 as i32;

                // Normalize direction (sign only)
                let dir_changed = if dx1 == 0 && dy1 == 0 {
                    false // seg_start == prev, no direction yet
                } else {
                    dx1.signum() != dx2.signum() || dy1.signum() != dy2.signum()
                };

                if dir_changed {
                    segments.push(make_segment(grid, net_id, seg_start, prev, trace_width));
                    seg_start = prev;
                }
            }

            prev = node;
        }

        // Emit final segment
        if seg_start != prev {
            segments.push(make_segment(grid, net_id, seg_start, prev, trace_width));
        }
    }

    (segments, vias)
}

fn make_segment(
    grid: &RoutingGrid,
    net_id: NetId,
    from: GridNode,
    to: GridNode,
    width: Nm,
) -> RouteSegment {
    let start = grid.grid_to_nm(from.0 as u32, from.1 as u32);
    let end = grid.grid_to_nm(to.0 as u32, to.1 as u32);
    let layer = index_to_layer(from.2 as usize);
    RouteSegment::new(net_id, layer, width, start, end)
}

/// Rotate a point around the origin by the given angle in degrees.
fn rotate_point(p: Point, degrees: f64) -> Point {
    if degrees.abs() < 0.001 {
        return p;
    }
    let rad = degrees.to_radians();
    let cos = rad.cos();
    let sin = rad.sin();
    let x = p.x.raw() as f64;
    let y = p.y.raw() as f64;
    Point::new(
        Nm::new((x * cos - y * sin).round() as i64),
        Nm::new((x * sin + y * cos).round() as i64),
    )
}

#[cfg(test)]
mod tests {
    use super::*;
    use cypcb_core::Nm;
    use cypcb_rules::signal_class::{SignalClass, SignalClassConstraints};
    use cypcb_rules::{DesignConstraints, RoutingRuleSet};

    struct TestRules {
        base: DesignConstraints,
    }

    impl TestRules {
        fn new() -> Self {
            Self {
                base: DesignConstraints::default(),
            }
        }
    }

    impl RoutingRuleSet for TestRules {
        fn constraints_for_net(&self, _net_id: u32) -> &DesignConstraints {
            &self.base
        }
        fn constraints_for_class(&self, class: SignalClass) -> SignalClassConstraints {
            class.default_constraints()
        }
        fn via_cost(&self, from_layer: u8, to_layer: u8) -> f64 {
            let span = (from_layer as i16 - to_layer as i16).unsigned_abs() as f64;
            span * 2.0
        }
        fn layer_change_cost(&self, layer: u8) -> f64 {
            if layer == 0 { 0.1 } else { 0.5 }
        }
        fn clearance_between(&self, _net_a: u32, _net_b: u32) -> Nm {
            self.base.min_clearance
        }
    }

    #[test]
    fn order_nets_short_before_long() {
        let short_net = NetRoute {
            net_id: NetId::new(1),
            net_name: "SHORT".into(),
            pads: vec![
                PadTarget {
                    position: Point::from_mm(0.0, 0.0),
                    layer_mask: 1,
                    pad_size: (Nm::from_mm(0.6), Nm::from_mm(0.5)),
                    pin: "1".into(),
                },
                PadTarget {
                    position: Point::from_mm(1.0, 0.0),
                    layer_mask: 1,
                    pad_size: (Nm::from_mm(0.6), Nm::from_mm(0.5)),
                    pin: "2".into(),
                },
            ],
        };

        let long_net = NetRoute {
            net_id: NetId::new(2),
            net_name: "LONG".into(),
            pads: vec![
                PadTarget {
                    position: Point::from_mm(0.0, 0.0),
                    layer_mask: 1,
                    pad_size: (Nm::from_mm(0.6), Nm::from_mm(0.5)),
                    pin: "1".into(),
                },
                PadTarget {
                    position: Point::from_mm(20.0, 10.0),
                    layer_mask: 1,
                    pad_size: (Nm::from_mm(0.6), Nm::from_mm(0.5)),
                    pin: "2".into(),
                },
            ],
        };

        let ratsnest = vec![long_net, short_net];
        let order = order_nets(&ratsnest);

        // Short net (index 1) should come before long net (index 0)
        assert_eq!(order[0], 1, "Short net should be first");
        assert_eq!(order[1], 0, "Long net should be second");
    }

    #[test]
    fn order_nets_power_last() {
        let signal_net = NetRoute {
            net_id: NetId::new(1),
            net_name: "SIGNAL".into(),
            pads: vec![
                PadTarget {
                    position: Point::from_mm(0.0, 0.0),
                    layer_mask: 1,
                    pad_size: (Nm::from_mm(0.6), Nm::from_mm(0.5)),
                    pin: "1".into(),
                },
                PadTarget {
                    position: Point::from_mm(20.0, 20.0),
                    layer_mask: 1,
                    pad_size: (Nm::from_mm(0.6), Nm::from_mm(0.5)),
                    pin: "2".into(),
                },
            ],
        };

        let vcc_net = NetRoute {
            net_id: NetId::new(2),
            net_name: "VCC".into(),
            pads: vec![
                PadTarget {
                    position: Point::from_mm(0.0, 0.0),
                    layer_mask: 1,
                    pad_size: (Nm::from_mm(0.6), Nm::from_mm(0.5)),
                    pin: "1".into(),
                },
                PadTarget {
                    position: Point::from_mm(1.0, 0.0),
                    layer_mask: 1,
                    pad_size: (Nm::from_mm(0.6), Nm::from_mm(0.5)),
                    pin: "2".into(),
                },
            ],
        };

        let gnd_net = NetRoute {
            net_id: NetId::new(3),
            net_name: "GND".into(),
            pads: vec![
                PadTarget {
                    position: Point::from_mm(0.0, 0.0),
                    layer_mask: 1,
                    pad_size: (Nm::from_mm(0.6), Nm::from_mm(0.5)),
                    pin: "1".into(),
                },
                PadTarget {
                    position: Point::from_mm(2.0, 0.0),
                    layer_mask: 1,
                    pad_size: (Nm::from_mm(0.6), Nm::from_mm(0.5)),
                    pin: "2".into(),
                },
            ],
        };

        let ratsnest = vec![vcc_net, signal_net, gnd_net];
        let order = order_nets(&ratsnest);

        // Signal net should come first (non-power), power/ground last
        assert_eq!(order[0], 1, "Signal net should be first");
        // VCC and GND are both power, should be at end
        assert!(
            order[1] == 0 || order[1] == 2,
            "Power nets should be at end"
        );
        assert!(
            order[2] == 0 || order[2] == 2,
            "Power nets should be at end"
        );
    }

    #[test]
    fn ripup_triggers_on_blocked_path() {
        use crate::grid::make_test_grid;
        use crate::pathfinder::find_path;

        // 30x20 grid, 2 layers — net 1 can reroute via layer 1
        let mut grid = make_test_grid(30, 20, 100_000, 2);
        let rules = TestRules::new();
        let config = AutorouteConfig {
            max_ripup_iterations: 3,
            ..Default::default()
        };

        // Route net 1 horizontally through y=10 on layer 0
        let cost1 = RoutingCost::new(&rules, 1, 1.0);
        let path1 = find_path(&mut grid, (0, 10, 0), (29, 10, 0), &cost1, false);
        assert!(path1.is_some(), "Net 1 should route on empty grid");

        // Build a ratsnest with net 1 (so rip-up can re-route it)
        // Pads are through-hole (layer_mask = 0b11) so reroute can use either layer
        let net1 = NetRoute {
            net_id: NetId::new(1),
            net_name: "NET1".into(),
            pads: vec![
                PadTarget {
                    position: Point::new(Nm::new(0), Nm::new(1_000_000)),
                    layer_mask: 0b11,
                    pad_size: (Nm::new(100_000), Nm::new(100_000)),
                    pin: "1".into(),
                },
                PadTarget {
                    position: Point::new(Nm::new(2_900_000), Nm::new(1_000_000)),
                    layer_mask: 0b11,
                    pad_size: (Nm::new(100_000), Nm::new(100_000)),
                    pin: "2".into(),
                },
            ],
        };
        let ratsnest = vec![net1];

        let mut routed_paths: HashMap<u32, Vec<Vec<GridNode>>> = HashMap::new();
        routed_paths.insert(1, vec![path1.unwrap()]);

        // Pad zones for net 2 (the current net being routed)
        let net2_pad_zones = vec![
            PadZone { cx: 15, cy: 0, radius: 2 },
            PadZone { cx: 15, cy: 19, radius: 2 },
        ];

        // Net 2 needs to go from (15, 0) to (15, 19) — crosses net 1
        let conn_attempt = ConnectionAttempt {
            start: (15, 0, 0),
            end: (15, 19, 0),
            any_end: false,
            net_id: 2,
            pad_zones: &net2_pad_zones,
        };
        let result = attempt_ripup_reroute(
            &mut grid,
            &conn_attempt,
            &mut routed_paths,
            &ratsnest,
            &rules,
            &config,
        );

        // The rip-up should have succeeded: removed net 1, routed net 2,
        // then re-routed net 1 (can use layer 1 to go around net 2)
        assert!(
            result.is_some(),
            "Rip-up/reroute should succeed for crossing nets"
        );

        // Net 1 should still be in routed_paths (re-routed)
        assert!(
            routed_paths.contains_key(&1),
            "Victim net 1 should be re-routed"
        );
    }

    #[test]
    fn spanning_tree_produces_n_minus_1_edges() {
        let pads: Vec<PadTarget> = (0..5)
            .map(|i| PadTarget {
