            RulesPreset::from_name("JLCPCB"),
            Some(RulesPreset::JlcpcbStandard2Layer)
        );
        assert_eq!(
            RulesPreset::from_name("jlcpcb-2layer"),
            Some(RulesPreset::JlcpcbStandard2Layer)
        );
