            RulesPreset::from_name("jlcpcb_standard"),
            Some(RulesPreset::JlcpcbStandard2Layer)
        );
        assert_eq!(
            RulesPreset::from_name("jlcpcb_4layer"),
            Some(RulesPreset::JlcpcbStandard4Layer)
        );
        assert_eq!(
            RulesPreset::from_name("jlcpcb-advanced"),
